<?php

declare(strict_types=1);

namespace App\Features\Blog\App\Services;

use App\Features\Blog\Domain\RepositoryInterfaces\ArticleRepositoryInterface;
use App\Features\Shared\Domain\ValueObjects\Slug;

/**
 * The article slug resolution: slugs are auto-generated from the EN
 * title (via the shared {@see Slug} — English and Russian input both
 * work, Cyrillic is transliterated) and editable in the form. The
 * server distinguishes the auto-generated value from a manual override
 * and re-resolves it:
 *
 * - submitted == the naive auto-generation of the EN title (or == the
 *   currently STORED slug on update — the regeneration trigger) →
 *   regenerate server-side, appending a numeric collision suffix when
 *   the base slug is taken (`my-post`, `my-post-2`, `my-post-3` …);
 * - submitted != either → a manual override, kept as-is (the request
 *   validation rejects an override that collides).
 *
 * The suffix query covers ALL articles including trashed ones — soft-
 * deleted entities occupy their slug. The persistence lookup is
 * the repository's `takenSlugs()` — no framework or DB dependency
 * lives in this service.
 */
final class ArticleSlugService
{
    public function __construct(
        private readonly ArticleRepositoryInterface $repository,
    ) {
    }

    public function resolve(
        string $submittedSlug,
        ?string $storedSlug,
        string $enTitle,
        ?int $ignoreId,
    ): Slug {
        if (! $this->isAutoGenerated($submittedSlug, $storedSlug, $enTitle)) {
            return new Slug($submittedSlug);
        }

        $generated = Slug::generate($enTitle);
        $base = $generated === '' ? 'article' : $generated;

        $taken = $this->repository->takenSlugs($base, $ignoreId);

        if (! in_array($base, $taken, true)) {
            return new Slug($base);
        }

        $maxSuffix = 0;
        foreach ($taken as $slug) {
            if (preg_match('/^'.preg_quote($base, '/').'-(\d+)$/', $slug, $matches) === 1) {
                $maxSuffix = max($maxSuffix, (int) $matches[1]);
            }
        }

        return new Slug($base.'-'.($maxSuffix + 1));
    }

    /**
     * Whether a submitted slug is the "auto-generated" value — equal to
     * the naive generation of the EN title (the client regenerates the
     * slug on every EN-title save) or the currently stored slug on
     * update (the regeneration trigger). Such values are re-resolved
     * server-side with a collision suffix; a differing submission is a
     * manual override kept as-is — its uniqueness is the store/update
     * validator's job.
     */
    public function isAutoGenerated(
        string $submittedSlug,
        ?string $storedSlug,
        string $enTitle,
    ): bool {
        return $submittedSlug === Slug::generate($enTitle) || $submittedSlug === $storedSlug;
    }
}
